insert into app.business_rule_catalog(rule_key,domain,title,description,source,precedence,enforcement,status,test_status,source_ref,metadata)
values
('CALLUP-001','sports','Convocatoria is a pre-match selected roster','Legacy persisted the Convocatoria module and write permissions for Presidencia, Operaciones and Formadores, but no RSVP/response entity. V2 therefore stores only selected/not-selected roster plus optional note per scheduled match and Tanner.','legacy',90,'command','active','tested','SaaS foundation convocatoria permissions / app.match_callups','{"qa":"Formadores select+deselect; completed match locked; rollback clean"}'::jsonb),
('CALLUP-002','sports','Callup roster is category-safe','For a match with category, Convocatoria only surfaces active Tanners in that category and the backend rejects selecting a Tanner outside it.','approved_v2',100,'command','active','tested','private.query_callup_roster / private.command_set_callup','{"qa":"eligible roster filtered by match category"}'::jsonb)
